import JSON
using SpecialFunctions

"""
	gen( x, name )

Generate fixture data for the modified Bessel function of the
second kind of order one (K₁) and write to file.

# Arguments

* `x`: domain (positive values only)
* `name::AbstractString`: output filename

# Examples

```julia
julia> x = range( 1.0e-6, stop = 10.0, length = 2001 );
julia> gen( x, "data.json" );
```
"""
function gen( x, name )
	y = Array{Float64}( undef, length(x) );
	for i in eachindex(x)
		y[i] = besselk( 1, x[i] );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Very small values:
x = range( 1.0e-5, stop = 0.8, length = 5003 );
gen( x, "very_small.json" );

# Positive small values:
x = range( 0.8, stop = 3.0, length = 5003 );
gen( x, "small_positive.json" );

# Positive medium values:
x = range( 3.0, stop = 20.0, length = 5003 );
gen( x, "medium_positive.json" );

# Positive Large values:
x = range( 20.0, stop = 50.0, length = 5003 );
gen( x, "large_positive.json" );
